function getWeapon(id) { return WEAPONS.find(w => w.id === id) || WEAPONS[0]; }
/* 强化归属副武器判定：weaponOnly / weaponMatch / wakeFor 命中副武器 id 时返回 WEAPON 定义，否则 null
   （用于局内强化卡显示副武器专属词条与独特配色） */
function weaponOfUpgrade(u) {
  if (!u) return null;
  let wid = null;
  if (u.weaponOnly) wid = u.weaponOnly[0];
  else if (u.weaponMatch) wid = u.weaponMatch.find(id => { const w = getWeapon(id); return w && w.id !== 'none' && !getClass(id); });
  else if (u.wakeFor && u.wakeFor !== '*' && !getClass(u.wakeFor)) wid = u.wakeFor;
  if (!wid) return null;
  const w = getWeapon(wid);
  return (w && w.id !== 'none') ? w : null;
}


function effectiveTalentLv(T, lv) {
  if (T.branch === 'CROWN' || lv <= 0) return lv;
  const D = GAME_CONFIG.tunables.talentDecay;
  if (lv < D.startLv) return lv;
  return (D.startLv - 1) + (lv - (D.startLv - 1)) * D.factor;
}

/* 职业基础值 + 主页天赋 → 实际初始属性 */
function buildBase(classId) {
  const cls = getClass(classId) || getClass('metal_sword');
  const base = Object.assign({}, CLASS_DEFAULTS, cls.stats);
  const t = getMeta().talents;
  const tl = id => t[id] || 0;
  // ⚠️ ⬇⬇ 新天赋树：逐个 apply(base, 等效等级) — 比旧版手动 map 字段稳定
  for (const T of TALENTS) {
    const lv = tl(T.id);
    if (lv > 0 && typeof T.apply === 'function') T.apply(base, effectiveTalentLv(T, lv));
  }
  // S-02 幸运线附带战斗/经济属性：每级移速 +1%、金币 +2%
  const _lkLv = Math.min(GAME_CONFIG.luck.maxLevel, getMeta().luck || 0);
  if (_lkLv > 0) {
    base.speedMul *= 1 + GAME_CONFIG.luck.speedPerLevel * _lkLv;
    base.coinMul *= 1 + GAME_CONFIG.luck.coinPerLevel * _lkLv;
  }
  return base;
}

