    this.plantSynDmg = 0.03;                         // 每株伤害加成
    this.plantSynAtk = 0.02;                         // 每株攻速加成
    this.plantSynMaxStacks = 20;                     // 最大层数
    this.vineEntangle = false;                       // 藤蔓缠绕（定身）
    this.vineEntangleChance = 0.15;                  // 定身概率
    this.vineEntangleDur = 1.2;                      // 定身时长
    this.seedRain = false;                           // 种子雨
